import React, { useEffect, useState } from 'react';
import admin from '../services/admin';
import { useNavigate } from 'react-router-dom';

export default function AdminDashboard() {
  const [loading, setLoading] = useState(true);
  const [bookings, setBookings] = useState([]);
  const [error, setError] = useState(null);
  const navigate = useNavigate();

  useEffect(() => {
    let mounted = true;
    setLoading(true);
    admin.fetchAdmin('/bookings.json').then(res => {
      if (!mounted) return;
      if (!res.success) {
        if (res.status === 401) { navigate('/admin/login'); return; }
        setError(res.error || 'Failed to load');
      } else {
        setBookings(res.data.bookings || []);
      }
    }).catch(err => setError(err && err.message ? err.message : 'Network error')).finally(() => mounted && setLoading(false));
    return () => { mounted = false; };
  }, [navigate]);

  async function doLogout(){
    await admin.logout();
    navigate('/admin/login');
  }

  return (
    <div className="min-h-screen bg-gray-50 p-6">
      <div className="max-w-6xl mx-auto bg-white shadow rounded p-4">
        <div className="flex items-center justify-between mb-4">
          <h2 className="text-xl font-semibold">Bookings</h2>
          <div>
            <button onClick={doLogout} className="px-3 py-2 bg-red-600 text-white rounded">Logout</button>
          </div>
        </div>
        {loading && <div>Loading...</div>}
        {error && <div className="text-red-600">{error}</div>}
        {!loading && !error && (
          <table className="w-full table-auto border-collapse">
            <thead>
              <tr className="text-left border-b"><th className="p-2">ID</th><th className="p-2">Name</th><th className="p-2">Phone</th><th className="p-2">Date</th><th className="p-2">Slot</th><th className="p-2">Payment</th></tr>
            </thead>
            <tbody>
              {bookings.map(b => (
                <tr key={b.id} className="border-b hover:bg-gray-50">
                  <td className="p-2 font-mono text-sm">{b.id}</td>
                  <td className="p-2">{b.name}</td>
                  <td className="p-2">{b.phone}</td>
                  <td className="p-2">{b.date}</td>
                  <td className="p-2">{b.slot}</td>
                  <td className="p-2">
                    {b.paymentRequired ? (
                      <div className="flex items-center gap-2">
                        <div className="text-sm">{b.paymentStatus || 'pending'}</div>
                        {b.paymentStatus !== 'paid' && (
                          <button onClick={async () => {
                            const prev = bookings.slice();
                            // optimistic update
                            setBookings(bookings.map(x => x.id === b.id ? Object.assign({}, x, { paymentStatus: 'paid' }) : x));
                            const r = await admin.fetchAdmin(`/bookings/${encodeURIComponent(b.id)}/mark-paid`, { method: 'POST' });
                            if (!r.success) {
                              setBookings(prev);
                              setError(r.error || 'Failed to mark paid');
                            }
                          }} className="px-2 py-1 bg-green-600 text-white rounded text-xs">Mark paid</button>
                        )}
                      </div>
                    ) : '-'}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}
