// admin.js
// Small helper to handle admin login and automatically include CSRF token for admin requests.

const CSRF_KEY = 'admin_csrf_token';

function saveCsrf(token) {
  try { localStorage.setItem(CSRF_KEY, token); } catch (e) { /* ignore storage errors */ }
}

function clearCsrf() {
  try { localStorage.removeItem(CSRF_KEY); } catch (e) {}
}

function readCsrf() {
  try { return localStorage.getItem(CSRF_KEY); } catch (e) { return null; }
}

export async function login(user, pass) {
  try {
    const res = await fetch('/admin/login', {
      method: 'POST',
      credentials: 'include',
      headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' },
      body: JSON.stringify({ user, pass }),
    });
    const j = await (res.ok ? res.json() : res.json().catch(() => ({})));
    if (res.ok && j && j.ok) {
      if (j.csrf) saveCsrf(j.csrf);
      return { success: true, csrf: j.csrf };
    }
    // audit or surface server message
    return { success: false, status: res.status, error: (j && j.error) || 'login_failed' };
  } catch (err) {
    return { success: false, error: err && err.message ? err.message : 'network_error' };
  }
}

export async function logout() {
  try {
    const res = await fetch('/admin/logout', { method: 'POST', credentials: 'include' });
    clearCsrf();
    return { success: res.ok };
  } catch (err) {
    clearCsrf();
    return { success: false, error: err && err.message ? err.message : 'network_error' };
  }
}

// Try to obtain a CSRF token from storage or by probing GET /admin/login (it returns csrf when already logged in)
export async function getCsrf() {
  const stored = readCsrf();
  if (stored) return stored;
  try {
    const res = await fetch('/admin/login', { method: 'GET', credentials: 'include', headers: { Accept: 'application/json' } });
    if (!res.ok) return null;
    const j = await res.json().catch(() => null);
    if (j && j.ok && j.csrf) {
      saveCsrf(j.csrf);
      return j.csrf;
    }
    return null;
  } catch (e) {
    return null;
  }
}

// Convenience wrapper to call /admin/* endpoints. Automatically includes credentials and CSRF for state-changing methods.
export async function fetchAdmin(path, opts = {}) {
  const method = (opts.method || 'GET').toUpperCase();
  const headers = Object.assign({}, opts.headers || {});
  // ensure Accept/Content-Type are sensible when sending JSON
  if (opts.body && !headers['Content-Type']) headers['Content-Type'] = 'application/json';
  if (!headers['Accept']) headers['Accept'] = 'application/json';

  if (['POST', 'PUT', 'DELETE', 'PATCH'].includes(method)) {
    const csrf = await getCsrf();
    if (!csrf) return { success: false, error: 'not_authenticated' };
    headers['X-CSRF-Token'] = csrf;
  }

  const res = await fetch('/admin' + path, {
    method,
    credentials: 'include',
    headers,
    body: opts.body,
  }).catch(err => ({ ok: false, error: err }));

  if (!res || !res.ok) {
    // if unauthorized, clear cached csrf so UI can re-auth
    if (res && (res.status === 401 || res.status === 403)) clearCsrf();
    return { success: false, status: res && res.status, error: res && res.error ? res.error : 'request_failed' };
  }

  // parse json if possible
  try {
    const j = await res.json().catch(() => null);
    return { success: true, status: res.status, data: j };
  } catch (e) {
    return { success: true, status: res.status, data: null };
  }
}

export default { login, logout, getCsrf, fetchAdmin };
